<?php require dirname(__DIR__).'/app/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}check_csrf();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="flawed-orders-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Reference','Customer','Phone','Email','Address','Area','Subtotal BDT','Discount BDT','Delivery BDT','Total BDT','Status','Payment','Created']);$q=query('SELECT reference,customer_name,phone,email,address,area,subtotal,COALESCE((SELECT amount FROM order_discounts d WHERE d.order_id=orders.id),0),delivery_fee,total,status,payment_status,created_at FROM orders ORDER BY id DESC');while($row=$q->fetch(PDO::FETCH_NUM)){fputcsv($out,array_map(function($v){$v=(string)($v??'');return preg_match('/^[\s]*[=+@-]/u',$v)?"'".$v:$v;},$row));}fclose($out);
